-- =====================================================================
-- Migration 093 — more built-in loading schemes (generated from
-- src/lib/programming/scheme-presets.ts). Skips any name that already exists.
-- =====================================================================
insert into public.loading_schemes (name, description, load_type, weeks, sort)
select v.name, v.description, v.load_type, v.weeks, v.sort
from (values
  ('5x5 building (RPE)', 'Five sets of five. Effort climbs each week, then a lighter week 4.', 'rpe', '[[{"r":"5","e":7},{"r":"5","e":7},{"r":"5","e":7},{"r":"5","e":7},{"r":"5","e":7}],[{"r":"5","e":7.5},{"r":"5","e":7.5},{"r":"5","e":7.5},{"r":"5","e":7.5},{"r":"5","e":7.5}],[{"r":"5","e":8},{"r":"5","e":8},{"r":"5","e":8},{"r":"5","e":8},{"r":"5","e":8}],[{"r":"5","e":6},{"r":"5","e":6},{"r":"5","e":6}]]'::jsonb, 20),
  ('Linear % 4x6 > 4x5 > 4x4 + deload', 'Classic strength block off a 1RM. Reps drop as load climbs; week 4 lighter.', 'percent', '[[{"r":"6","p":70},{"r":"6","p":70},{"r":"6","p":70},{"r":"6","p":70}],[{"r":"5","p":75},{"r":"5","p":75},{"r":"5","p":75},{"r":"5","p":75}],[{"r":"4","p":80},{"r":"4","p":80},{"r":"4","p":80},{"r":"4","p":80}],[{"r":"5","p":60},{"r":"5","p":60},{"r":"5","p":60}]]'::jsonb, 21),
  ('Heavy triples 5x3 (%)', 'Max strength. Small jumps each week, deload in week 4.', 'percent', '[[{"r":"3","p":80},{"r":"3","p":80},{"r":"3","p":80},{"r":"3","p":80},{"r":"3","p":80}],[{"r":"3","p":82.5},{"r":"3","p":82.5},{"r":"3","p":82.5},{"r":"3","p":82.5},{"r":"3","p":82.5}],[{"r":"3","p":85},{"r":"3","p":85},{"r":"3","p":85},{"r":"3","p":85},{"r":"3","p":85}],[{"r":"3","p":70},{"r":"3","p":70},{"r":"3","p":70}]]'::jsonb, 22),
  ('Top set + back-offs', 'One heavy top set, then three back-off sets of five. Top set gets heavier each week.', 'percent', '[[{"r":"3","p":85},{"r":"5","p":75},{"r":"5","p":75},{"r":"5","p":75}],[{"r":"2","p":88},{"r":"5","p":77.5},{"r":"5","p":77.5},{"r":"5","p":77.5}],[{"r":"1","p":92},{"r":"5","p":80},{"r":"5","p":80},{"r":"5","p":80}]]'::jsonb, 23),
  ('Strength-speed 6x2 (70-75%)', 'Moderate load moved as fast as possible. Great in fight camp.', 'percent', '[[{"r":"2","p":70},{"r":"2","p":70},{"r":"2","p":70},{"r":"2","p":70},{"r":"2","p":70},{"r":"2","p":70}],[{"r":"2","p":72.5},{"r":"2","p":72.5},{"r":"2","p":72.5},{"r":"2","p":72.5},{"r":"2","p":72.5},{"r":"2","p":72.5}],[{"r":"2","p":75},{"r":"2","p":75},{"r":"2","p":75},{"r":"2","p":75},{"r":"2","p":75},{"r":"2","p":75}]]'::jsonb, 24),
  ('Speed-strength 5x3 (30-40%)', 'Light, fast and explosive: loaded jumps, trap bar jumps, speed pulls.', 'percent', '[[{"r":"3","p":30},{"r":"3","p":30},{"r":"3","p":30},{"r":"3","p":30},{"r":"3","p":30}],[{"r":"3","p":35},{"r":"3","p":35},{"r":"3","p":35},{"r":"3","p":35},{"r":"3","p":35}],[{"r":"3","p":40},{"r":"3","p":40},{"r":"3","p":40},{"r":"3","p":40},{"r":"3","p":40}]]'::jsonb, 25),
  ('Hypertrophy 4x10 > 4x8 > 4x6', 'Off-season size block. Reps drop and effort builds over three weeks.', 'rpe', '[[{"r":"10","e":7},{"r":"10","e":7},{"r":"10","e":7},{"r":"10","e":7}],[{"r":"8","e":7.5},{"r":"8","e":7.5},{"r":"8","e":7.5},{"r":"8","e":7.5}],[{"r":"6","e":8},{"r":"6","e":8},{"r":"6","e":8},{"r":"6","e":8}]]'::jsonb, 26),
  ('Strength endurance 3x15 > 3x12 > 3x10', 'Accessories, rehab and general prep. Easy effort that slowly builds.', 'rpe', '[[{"r":"15","e":6},{"r":"15","e":6},{"r":"15","e":6}],[{"r":"12","e":6.5},{"r":"12","e":6.5},{"r":"12","e":6.5}],[{"r":"10","e":7},{"r":"10","e":7},{"r":"10","e":7}]]'::jsonb, 27),
  ('Descending pyramid 4/6/8/10', 'Heaviest set first while fresh, then lighter sets for more reps.', 'rpe', '[[{"r":"4","e":8.5},{"r":"6","e":8},{"r":"8","e":7.5},{"r":"10","e":7}]]'::jsonb, 28),
  ('RPE wave 5/3/1 (no max needed)', 'The 5/3/1 feel by effort instead of percentages. Week 3 is lighter.', 'rpe', '[[{"r":"5","e":7},{"r":"3","e":8},{"r":"1","e":9}],[{"r":"5","e":7.5},{"r":"3","e":8.5},{"r":"1","e":9.5}],[{"r":"5","e":6},{"r":"5","e":6},{"r":"5","e":6}]]'::jsonb, 29),
  ('Deload week', 'One easy week: fewer sets, lower effort. Use before a test or a fight.', 'rpe', '[[{"r":"5","e":6},{"r":"5","e":6},{"r":"5","e":6}]]'::jsonb, 40)
) as v(name, description, load_type, weeks, sort)
where not exists (select 1 from public.loading_schemes s where lower(s.name) = lower(v.name));
